from z3 import *
import itertools

# variables
X = [Int(f'x{i}') for i in range(81)]
solver = Solver()
for v in X:
    solver.add(And(v>=1, v<=9))
# rows
for r in range(9):
    solver.add(Distinct([X[r*9+c] for c in range(9)]))
# cols
for c in range(9):
    solver.add(Distinct([X[r*9+c] for r in range(9)]))
# blocks
for br in range(3):
    for bc in range(3):
        cells = []
        for dr in range(3):
            for dc in range(3):
                cells.append(X[(br*3+dr)*9 + (bc*3+dc)])
        solver.add(Distinct(cells))
# clues
clues = {2:3,11:6,13:8,20:9,22:2,35:7,42:2,46:9,50:4,57:6,58:4,60:9,62:8,69:5,78:6,79:4}
for idx,val in clues.items():
    solver.add(X[idx]==val)

if solver.check()==sat:
    m=solver.model()
    sol=[m.evaluate(v).as_long() for v in X]
    print(sol)
else:
    print('unsat')
